head.script:
// 테스트 설명, 유효성 값 설정
//  - 담당 범위 : 마스크 문자별 입력 제한 (# / A / a / Z / z / S / X,9 / * / K), 불일치 문자 미입력, 왼쪽부터 매칭과 일반 문자 고정
//  - 특수 기호(||, {,}, !) 는 _2, maxLength / applyFormat / displayFormat 연동 / DataList 반영은 _3 담당
scwin.tData = {
    "description" : "[column > P > editFormat]<br/>inputType='text' 인 Column 에 값을 입력중이거나 값이 표시될때 적용할 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "포맷을 # 로 설정 시, '0~9' 의 숫자만 입력할 수 있습니다.",
        "포맷을 A 로 설정 시, 'A~Z' 의 대문자 알파벳만 입력할 수 있습니다.",
        "포맷을 a 로 설정 시, 'a~z' 의 소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 Z 로 설정 시, '0~9', 'A~Z' 의 숫자와 대문자 알파벳만 입력할 수 있습니다.",
        "포맷을 z 로 설정 시, '0~9', 'a~z' 의 숫자와 소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 S 로 설정 시, 'a~z', 'A~Z' 의 대/소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 X,9 로 설정 시, '0~9', 'a~z,A~Z' 의 숫자와 대/소문자 알파벳만 입력할 수 있습니다.",
        "포맷을 * 로 설정 시, '0~9', 'a~z,A~Z', '~!@#$%^&*()_+|-=\\{}[]:';'<>?,./' 의 숫자와 대/소문자 알파벳, 특수문자를 입력할 수 있으며 입력값은 '*' 문자로 표시됩니다.",
        "포맷을 K 로 설정 시, 'ㄱ~ㅎ,ㅏ~ㅣ,가~힣' 의 모든 한글만 입력할 수 있습니다. (다른 마스크 문자와 함께 사용할 수 없습니다)",
        "입력 문자가 마스크 문자와 맞지 않으면 입력되지 않습니다.",
        "입력값에 맞춰 마스크 문자가 왼쪽부터 매칭되며 마스크 문자가 아닌 경우 그대로 표시되고 수정할 수 없습니다.",
    ]
}



scwin.gVar = {
    // Row 별 입력 문자열 (Row 0 : 영문 대/소문자, 숫자, 특수문자 혼합 / Row 1 : 한글 / Row 2 : 일반 문자 자리까지 포함한 값)
    "inputValues" : ["aA1!bB2@cC3#", "가나다라마바", "OZ101-14K"],
    // Row 별 편집 중 입력창 값 기록 (해당 Row 셀 더블클릭 시 초기화)
    "editValue" : {}
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_editFormat.setValue("######");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - input : 입력할 문자열 안내 Column (readOnly)
//  - val : 검증 대상 Column (inputType=text, editFormat 을 옵션값으로 설정, 빈 값에서 입력 시작)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.editValue = {};

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] editFormat 선택 -> Target 재생성 -> 결과창 clear\n[절차] Row 별로 val 셀 더블클릭 -> 입력 문자열 Column 의 문자열을 한 자씩 키보드로 입력 -> 셀 밖 클릭으로 포커스 해제 (Row 1 은 한글 입력기로 입력)\n[확인] 셀 표시값 확인 버튼 -> 키 입력마다의 입력창 값, 편집 종료 후 셀 표시값, DataList 값"', '', 'label1');

    let cEditFormat = con_editFormat.getValue();

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="input" name="input" dataType="text"></w2:column>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let arrData = [];
    for (let i = 0; i < scwin.gVar.inputValues.length; i++) {
        arrData.push({ "input" : scwin.gVar.inputValues[i], "val" : "" });
    }
    dlt_bind.setJSON(arrData, false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="입력 문자열"></w2:column>';
    strTarget += '<w2:column width="320" style="" inputType="text" id="column2" value="val (' + cEditFormat + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="input" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="320" style="" inputType="text" id="val" value="" dataType="text" editFormat="' + cEditFormat + '"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 편집 입력창 값 기록
    //  - 셀 더블클릭(편집 진입) 시 해당 Row 기록을 초기화하고 편집 진입 직후 입력창 값을 첫 값으로 기록
    //  - 키를 뗄 때 / 입력이 반영될 때마다 입력창 값 기록
    target1.render.addEventListener("dblclick", function () {
        setTimeout(function () {
            let row = target1.getFocusedRowIndex();
            scwin.gVar.editValue[row] = [];
            let elem = document.activeElement;
            if (elem && elem.tagName === "INPUT" && target1.render.contains(elem)) {
                scwin.gVar.editValue[row].push(elem.value);
            }
        }, 0);
    }, true);
    target1.render.addEventListener("keyup", scwin.recordEditValue, true);
    target1.render.addEventListener("input", scwin.recordEditValue, true);
}



// 편집 중 입력창 값을 기록 (입력창의 포맷 처리가 끝난 뒤의 값을 읽는다, 직전 기록과 같으면 생략)
scwin.recordEditValue = function (e) {
    let elem = e.target;
    if (!elem || elem.tagName !== "INPUT") {
        return;
    }
    setTimeout(function () {
        let arr = scwin.gVar.editValue[target1.getFocusedRowIndex()];
        if (!arr) {
            return;
        }
        if (arr.length === 0 || arr[arr.length - 1] !== elem.value) {
            arr.push(elem.value);
        }
    }, 0);
}



// val 셀의 화면 표시값
scwin.getCellText = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_1']");
    return td ? td.textContent : "";
}



// 설정 조건, Row 별 편집 중 입력창 값 -> 셀 표시값 -> DataList 값 출력
//  - validation 1~9 : 마스크 문자별 입력 허용 문자 (키 입력마다의 입력창 값), * 의 '*' 표시, K 와 다른 마스크 문자 혼용
//  - validation 10 : 마스크 문자와 맞지 않는 입력 문자가 입력창 값에 추가되지 않음
//  - validation 11 : 왼쪽부터 매칭, 일반 문자(- 등) 자동 표시와 입력 시 고정
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("editFormat : " + con_editFormat.getValue());

    for (let i = 0; i < scwin.gVar.inputValues.length; i++) {
        let arrText = [];
        let arrEdit = scwin.gVar.editValue[i];
        if (arrEdit && arrEdit.length > 0) {
            arrText.push("편집 중 입력창 값 : " + arrEdit.join(" > "));
        }
        arrText.push("셀 표시값 : " + scwin.getCellText(i));
        arrText.push("DataList 값 : " + dlt_bind.getCellData(i, "val"));
        bottom.setReturnValue("Row " + i + " " + arrText.join(" -> "));
    }
}
